1	package batchreg
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"strconv"
10		"strings"
11		"testing"
12	)
13	
14	// This file is the regression net for Save when the caller supplies the whole
15	// registry table directly, rather than building it through Register or
16	// Import. The rule under guard: a save that succeeds must read back through
17	// Load exactly as supplied, while a rejected save behaves as if it never ran —
18	// the target file's bytes and modification time stay untouched (or the file is
19	// never created), no temporary file remains, and the caller's records and
20	// their order are unchanged.
21	func saveBatch(batch, product string, quantity int64, unit string) Batch {
22		return Batch{Batch: batch, Product: product, Quantity: quantity, Unit: unit}
23	}
24	
25	func assertBatchesEqual(t *testing.T, got, want []Batch) {
26		t.Helper()
27		if len(got) != len(want) {
28			t.Fatalf("got %d records, want %d: %+v", len(got), len(want), got)
29		}
30		for i := range want {
31			if got[i] != want[i] {
32				t.Errorf("record %d = %+v, want %+v", i+1, got[i], want[i])
33			}
34		}
35	}
36	
37	// assertNoLeftoverTempFiles walks root and fails if any save temp file
38	// (".govflow-registry-*.tmp") survived a rejected save.
39	func assertNoLeftoverTempFiles(t *testing.T, root string) {
40		t.Helper()
41		err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
42			if err != nil || d.IsDir() {
43				return nil
44			}
45			if strings.HasPrefix(d.Name(), ".govflow-registry-") {
46				t.Errorf("rejected save left a temporary file behind: %s", path)
47			}
48			return nil
49		})
50		if err != nil {
51			t.Fatal(err)
52		}
53	}
54	
55	// With no batches, "batches" is written as an empty array, never null, whether
56	// the caller left the slice uninitialized or emptied it, and the file reads
57	// back as a usable empty version-1 registry.
58	func TestSaveEmptyRegistryWritesEmptyArrayAndReadsBack(t *testing.T) {
59		cases := []struct {
60			name    string
61			batches []Batch
62			wantNil bool
63		}{
64			{"uninitialized slice", nil, true},
65			{"already empty slice", []Batch{}, false},
66		}
67		for _, tc := range cases {
68			t.Run(tc.name, func(t *testing.T) {
69				path := filepath.Join(t.TempDir(), "registry.json")
70				reg := &Registry{Version: FormatVersion, Batches: tc.batches}
71				if err := Save(path, reg); err != nil {
72					t.Fatal(err)
73				}
74				data, err := os.ReadFile(path)
75				if err != nil {
76					t.Fatal(err)
77				}
78				if !bytes.Contains(data, []byte(`"batches": []`)) {
79					t.Fatalf("empty registry must serialize batches as [], got %s", data)
80				}
81				if bytes.Contains(data, []byte("null")) {
82					t.Fatalf("empty registry must not contain null: %s", data)
83				}
84				got, existed, err := Load(path)
85				if err != nil || !existed {
86					t.Fatalf("empty registry must read back: existed=%v err=%v", existed, err)
87				}
88				if got.Version != FormatVersion || len(got.Batches) != 0 {
89					t.Fatalf("read-back registry = %+v", got)
90				}
91				// Encoding takes a shallow copy, so the caller's slice header
92				// (nil included) must be left exactly as it was passed in.
93				if (reg.Batches == nil) != tc.wantNil {
94					t.Fatalf("Save mutated the Batches header: nil=%v, want nil=%v", reg.Batches == nil, tc.wantNil)
95				}
96			})
97		}
98	}
99	
100	// On success the records read back in submission order with all four fields
101	// intact: quantity bounds, legal Chinese, a genuine U+FFFD the caller typed,
102	// and whitespace of every kind kept verbatim.
103	func TestSaveRoundTripPreservesOrderAndFields(t *testing.T) {
104		fffd := string(rune(0xFFFD))
105		want := []Batch{
106			// Leading/trailing whitespace and legal Chinese stay verbatim;
107			// quantity at the inclusive lower bound.
108			saveBatch(" B-1 ", " 产品 A ", 1, " 千克 "),
109			// Interior whitespace is part of each text value.
110			saveBatch("B 2", "P  7", 7, "b o x"),
111			// Whitespace-only non-empty text; quantity at the inclusive upper bound.
112			saveBatch(" ", "\t", MaxQuantity, "\n"),
113			// A replacement character the caller genuinely entered is ordinary text.
114			saveBatch("批次-"+fffd, "P"+fffd+"Q", 42, fffd),
115		}
116		path := filepath.Join(t.TempDir(), "registry.json")
117		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), want...)}
118		if err := Save(path, reg); err != nil {
119			t.Fatal(err)
120		}
121		data, err := os.ReadFile(path)
122		if err != nil {
123			t.Fatal(err)
124		}
125		// The genuine U+FFFD is written as its real UTF-8 bytes, never stripped
126		// or re-encoded as an escape.
127		if !bytes.Contains(data, []byte{0xEF, 0xBF, 0xBD}) {
128			t.Fatalf("saved file lost the genuine U+FFFD: %s", data)
129		}
130	
131		got, existed, err := Load(path)
132		if err != nil || !existed {
133			t.Fatalf("saved registry must read back: existed=%v err=%v", existed, err)
134		}
135		if got.Version != FormatVersion {
136			t.Fatalf("read-back version = %d, want %d", got.Version, FormatVersion)
137		}
138		assertBatchesEqual(t, got.Batches, want)
139		// The caller's own records survive the save unchanged and in order.
140		assertBatchesEqual(t, reg.Batches, want)
141	}
142	
143	// Every invalid record rejects the whole save, and the error names the target
144	// file, the 1-based record position, the field and the reason. The batch id is
145	// cited verbatim only when the batch field itself is non-empty valid UTF-8; an
146	// empty or malformed id is never cited, and never replaced with U+FFFD to
147	// identify the record.
148	func TestSaveRejectsInvalidRecords(t *testing.T) {
149		fffd := string(rune(0xFFFD))
150		good := func() []Batch {
151			return []Batch{
152				saveBatch("B1", "P1", 1, "kg"),
153				saveBatch("B2", "P2", 2, "box"),
154				saveBatch("B3", "P3", 3, "m"),
155			}
156		}
157		cases := []struct {
158			name   string
159			mutate func([]Batch)
160			pos    int
161			field  string
162			batch  string // "" when the error must carry no batch id
163			reason string
164		}{
165			{"empty batch on first record", func(b []Batch) { b[0].Batch = "" }, 1, "batch", "", "must not be empty"},
166			{"empty product", func(b []Batch) { b[0].Product = "" }, 1, "product", "B1", "must not be empty"},
167			{"empty unit on second record", func(b []Batch) { b[1].Unit = "" }, 2, "unit", "B2", "must not be empty"},
168			{"zero quantity on second record", func(b []Batch) { b[1].Quantity = 0 }, 2, "quantity", "B2", "between 1 and"},
169			{"negative quantity on third record", func(b []Batch) { b[2].Quantity = -5 }, 3, "quantity", "B3", "between 1 and"},
170			{"malformed utf8 batch", func(b []Batch) { b[0].Batch = string([]byte{'B', 0xFF}) }, 1, "batch", "", "valid UTF-8"},
171			{"malformed utf8 product names valid batch", func(b []Batch) { b[2].Product = string([]byte{'P', 0xFF}) }, 3, "product", "B3", "valid UTF-8"},
172			{"malformed utf8 unit", func(b []Batch) { b[1].Unit = string([]byte{'k', 'g', 0xFF}) }, 2, "unit", "B2", "valid UTF-8"},
173		}
174		for _, tc := range cases {
175			t.Run(tc.name, func(t *testing.T) {
176				dir := t.TempDir()
177				path := filepath.Join(dir, "registry.json")
178				batches := good()
179				tc.mutate(batches)
180				submitted := append([]Batch(nil), batches...)
181				reg := &Registry{Version: FormatVersion, Batches: batches}
182	
183				err := Save(path, reg)
184				if err == nil {
185					t.Fatal("Save must reject the invalid table")
186				}
187				var fe *FormatError
188				if !errors.As(err, &fe) {
189					t.Fatalf("want *FormatError, got %v", err)
190				}
191				if fe.Position != tc.pos || fe.Field != tc.field || fe.Batch != tc.batch {
192					t.Fatalf("FormatError = position %d field %q batch %q, want position %d field %q batch %q",
193						fe.Position, fe.Field, fe.Batch, tc.pos, tc.field, tc.batch)
194				}
195				msg := err.Error()
196				for _, want := range []string{
197					path,
198					fmt.Sprintf("batches record %d", tc.pos),
199					strconv.Quote(tc.field),
200					tc.reason,
201				} {
202					if !strings.Contains(msg, want) {
203						t.Errorf("error %q must mention %q", msg, want)
204					}
205				}
206				if tc.batch == "" {
207					if strings.Contains(msg, "(batch \"") {
208						t.Errorf("error must not invent a batch id: %q", msg)
209					}
210				} else if !strings.Contains(msg, "(batch "+strconv.Quote(tc.batch)+")") {
211					t.Errorf("error must cite batch %q verbatim: %q", tc.batch, msg)
212				}
213				if strings.Contains(msg, fffd) {
214					t.Errorf("error must not identify a record via a substituted U+FFFD: %q", msg)
215				}
216	
217				// Rejection happens before any file system change.
218				if _, err := os.Stat(path); !os.IsNotExist(err) {
219					t.Fatalf("rejected save must not create the target file, stat err=%v", err)
220				}
221				assertNoLeftoverTempFiles(t, dir)
222				assertBatchesEqual(t, reg.Batches, submitted)
223			})
224		}
225	}
226	
227	// When earlier records are legal and a later one invalidates the table, no
228	// part of the earlier records may land: validation finishes (and fails)
229	// before any directory is created or any byte is written.
230	func TestSaveRejectsLateInvalidRecordWithoutPartialWrite(t *testing.T) {
231		cases := []struct {
232			name    string
233			batches []Batch
234			pos     int
235			field   string
236			batch   string
237			reason  string
238		}{
239			{
240				"empty unit on record 3",
241				[]Batch{
242					saveBatch("B1", "P1", 1, "kg"),
243					saveBatch("B2", "P2", 2, "box"),
244					saveBatch("B3", "P3", 3, ""),
245				},
246				3, "unit", "B3", "must not be empty",
247			},
248			{
249				"zero quantity on record 2",
250				[]Batch{
251					saveBatch("B1", "P1", 10, "kg"),
252					saveBatch("B2", "P2", 0, "box"),
253				},
254				2, "quantity", "B2", "between 1 and",
255			},
256			{
257				"malformed product on record 2",
258				[]Batch{
259					saveBatch("B1", "P1", 1, "kg"),
260					saveBatch("B2", string([]byte{'P', 0xFF}), 2, "box"),
261				},
262				2, "product", "B2", "valid UTF-8",
263			},
264		}
265		for _, tc := range cases {
266			t.Run(tc.name, func(t *testing.T) {
267				dir := t.TempDir()
268				// The parent directories do not exist either; a rejected save
269				// must not get far enough to create them.
270				path := filepath.Join(dir, "nested", "deep", "registry.json")
271				submitted := append([]Batch(nil), tc.batches...)
272				reg := &Registry{Version: FormatVersion, Batches: tc.batches}
273	
274				err := Save(path, reg)
275				if err == nil {
276					t.Fatal("Save must reject the table")
277				}
278				var fe *FormatError
279				if !errors.As(err, &fe) {
280					t.Fatalf("want *FormatError, got %v", err)
281				}
282				if fe.Position != tc.pos || fe.Field != tc.field || fe.Batch != tc.batch {
283					t.Fatalf("FormatError = position %d field %q batch %q, want %d %q %q",
284						fe.Position, fe.Field, fe.Batch, tc.pos, tc.field, tc.batch)
285				}
286				if !strings.Contains(err.Error(), tc.reason) {
287					t.Fatalf("error %q must mention %q", err.Error(), tc.reason)
288				}
289				if _, err := os.Stat(path); !os.IsNotExist(err) {
290					t.Fatalf("rejected save must not create the target file, stat err=%v", err)
291				}
292				if _, err := os.Stat(filepath.Dir(path)); !os.IsNotExist(err) {
293					t.Fatalf("rejected save must not create directories, stat err=%v", err)
294				}
295				assertNoLeftoverTempFiles(t, dir)
296				assertBatchesEqual(t, reg.Batches, submitted)
297			})
298		}
299	}
300	
301	// Two records sharing one byte-for-byte identical batch id reject the whole
302	// save even when product, quantity and unit are identical too. Save persists
303	// a complete table; it never applies Register/Import's duplicate-confirmation
304	// rule. The error names the id and both 1-based positions.
305	func TestSaveRejectsDuplicateBatchIDs(t *testing.T) {
306		cases := []struct {
307			name    string
308			batches []Batch
309			first   int
310			second  int
311			batch   string
312		}{
313			{
314				"identical records",
315				[]Batch{
316					saveBatch("DUP", "P", 5, "kg"),
317					saveBatch("DUP", "P", 5, "kg"),
318				},
319				1, 2, "DUP",
320			},
321			{
322				"first and third records",
323				[]Batch{
324					saveBatch("DUP", "P", 5, "kg"),
325					saveBatch("OTHER", "Q", 6, "g"),
326					saveBatch("DUP", "P", 5, "kg"),
327				},
328				1, 3, "DUP",
329			},
330			{
331				"identical whitespace-bearing id",
332				[]Batch{
333					saveBatch(" DUP ", "P", 5, "kg"),
334					saveBatch(" DUP ", "P", 5, "kg"),
335				},
336				1, 2, " DUP ",
337			},
338		}
339		for _, tc := range cases {
340			t.Run(tc.name, func(t *testing.T) {
341				dir := t.TempDir()
342				path := filepath.Join(dir, "registry.json")
343				submitted := append([]Batch(nil), tc.batches...)
344				reg := &Registry{Version: FormatVersion, Batches: tc.batches}
345	
346				err := Save(path, reg)
347				if err == nil {
348					t.Fatal("Save must reject duplicate batch ids")
349				}
350				var dup *DuplicateIDError
351				if !errors.As(err, &dup) {
352					t.Fatalf("want *DuplicateIDError, got %v", err)
353				}
354				if dup.Batch != tc.batch || dup.First != tc.first || dup.Second != tc.second {
355					t.Fatalf("DuplicateIDError = batch %q records %d,%d, want %q records %d,%d",
356						dup.Batch, dup.First, dup.Second, tc.batch, tc.first, tc.second)
357				}
358				msg := err.Error()
359				for _, want := range []string{
360					path,
361					strconv.Quote(tc.batch),
362					fmt.Sprintf("records %d and %d", tc.first, tc.second),
363				} {
364					if !strings.Contains(msg, want) {
365						t.Errorf("error %q must mention %q", msg, want)
366					}
367				}
368	
369				if _, err := os.Stat(path); !os.IsNotExist(err) {
370					t.Fatalf("rejected save must not create the target file, stat err=%v", err)
371				}
372				assertNoLeftoverTempFiles(t, dir)
373				assertBatchesEqual(t, reg.Batches, submitted)
374			})
375		}
376	}
377	
378	// Ids are compared by their original text: casing and leading or trailing
379	// whitespace distinguish batches, and tables using only such distinct ids
380	// save and read back normally.
381	func TestSaveDistinguishesBatchIDsVerbatim(t *testing.T) {
382		want := []Batch{
383			saveBatch("B-1", "P", 1, "kg"),
384			saveBatch("b-1", "P", 2, "kg"), // different case
385			saveBatch("B-1 ", "P", 3, "kg"),
386			saveBatch(" B-1", "P", 4, "kg"),
387		}
388		path := filepath.Join(t.TempDir(), "registry.json")
389		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), want...)}
390		if err := Save(path, reg); err != nil {
391			t.Fatalf("ids differing only by case or edge whitespace are distinct: %v", err)
392		}
393		got, existed, err := Load(path)
394		if err != nil || !existed {
395			t.Fatalf("saved registry must read back: existed=%v err=%v", existed, err)
396		}
397		assertBatchesEqual(t, got.Batches, want)
398	}
399	
400	// When the target already exists, any rejected save (invalid record, bad
401	// encoding or duplicate id) leaves its bytes and modification time exactly as
402	// they were; the old registry still loads with its original record.
403	func TestSaveRejectionKeepsExistingFileUnchanged(t *testing.T) {
404		const oldContent = `{"version":1,"batches":[{"batch":"OLD","product":"P","quantity":5,"unit":"kg"}]}`
405		bad := string([]byte{0xFF})
406		cases := map[string][]Batch{
407			"invalid later record": {
408				saveBatch("NEW1", "P", 1, "kg"),
409				saveBatch("NEW2", "", 2, "kg"),
410			},
411			"duplicate identical records": {
412				saveBatch("DUP", "P", 1, "kg"),
413				saveBatch("DUP", "P", 1, "kg"),
414			},
415			"malformed utf8": {
416				saveBatch("NEW1", "P", 1, "kg"),
417				saveBatch("N"+bad, "P", 2, "kg"),
418			},
419		}
420		for name, batches := range cases {
421			t.Run(name, func(t *testing.T) {
422				dir := t.TempDir()
423				path := filepath.Join(dir, "registry.json")
424				writeRegistry(t, path, oldContent)
425	
426				before, err := os.Stat(path)
427				if err != nil {
428					t.Fatal(err)
429				}
430				beforeBytes, err := os.ReadFile(path)
431				if err != nil {
432					t.Fatal(err)
433				}
434	
435				reg := &Registry{Version: FormatVersion, Batches: batches}
436				if err := Save(path, reg); err == nil {
437					t.Fatal("Save must reject the table")
438				}
439	
440				after, err := os.Stat(path)
441				if err != nil {
442					t.Fatal(err)
443				}
444				if after.ModTime() != before.ModTime() || after.Size() != before.Size() {
445					t.Fatalf("rejected save touched the file: before %+v, after %+v", before, after)
446				}
447				afterBytes, err := os.ReadFile(path)
448				if err != nil {
449					t.Fatal(err)
450				}
451				if string(afterBytes) != string(beforeBytes) {
452					t.Fatalf("rejected save changed the file bytes:\nbefore %s\nafter  %s", beforeBytes, afterBytes)
453				}
454				loaded, existed, err := Load(path)
455				if err != nil || !existed || len(loaded.Batches) != 1 || loaded.Batches[0].Batch != "OLD" {
456					t.Fatalf("old registry not preserved: %+v existed=%v err=%v", loaded, existed, err)
457				}
458				assertNoLeftoverTempFiles(t, dir)
459			})
460		}
461	}
462	
463	// Neither success nor failure may alter the records the caller supplied,
464	// including their order; the failure tables keep records around and after the
465	// offending one exactly as passed.
466	func TestSaveDoesNotMutateCallerRegistry(t *testing.T) {
467		fffd := string(rune(0xFFFD))
468		records := []Batch{
469			saveBatch(" B ", "P 1", 9, "kg"),
470			saveBatch("批次", "产品", MaxQuantity, "单位"),
471			saveBatch("x"+fffd, "y", 1, "z"),
472		}
473	
474		t.Run("successful save", func(t *testing.T) {
475			path := filepath.Join(t.TempDir(), "registry.json")
476			snapshot := append([]Batch(nil), records...)
477			reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), records...)}
478			if err := Save(path, reg); err != nil {
479				t.Fatal(err)
480			}
481			assertBatchesEqual(t, reg.Batches, snapshot)
482			if reg.Version != FormatVersion {
483				t.Fatalf("Version = %d", reg.Version)
484			}
485		})
486	
487		failures := map[string][]Batch{
488			"duplicate id in the middle": {
489				records[0], records[1], records[1], records[2],
490			},
491			"invalid record after valid prefix": {
492				records[0],
493				saveBatch("B2", "P", 0, "kg"),
494				records[2],
495			},
496		}
497		for name, batches := range failures {
498			t.Run(name, func(t *testing.T) {
499				path := filepath.Join(t.TempDir(), "registry.json")
500				snapshot := append([]Batch(nil), batches...)
501				reg := &Registry{Version: FormatVersion, Batches: batches}
502				if err := Save(path, reg); err == nil {
503					t.Fatal("Save must reject the table")
504				}
505				assertBatchesEqual(t, reg.Batches, snapshot)
506			})
507		}
508	}
