661	// ParseManifest decodes data as a non-empty JSON array holding exactly the
662	// four required fields batch, product, quantity and unit per element. The
663	// three text fields must be JSON strings that are not blank after trimming;
664	// quantity must be a JSON integer (no strings, fractions or exponents) in
665	// the range 1..MaxQuantity. An empty file, empty array, non-array document
666	// or any malformed record is rejected. The manifest bytes are never written.
667	func ParseManifest(data []byte) ([]Input, error) {
668		trimmed := bytes.TrimSpace(data)
669		if len(trimmed) == 0 {
670			return nil, errors.New("manifest file is empty")
671		}
672		if trimmed[0] != '[' {
673			return nil, errors.New("manifest must be a non-empty JSON array of records")
674		}
675	
676		var elems []json.RawMessage
677		dec := json.NewDecoder(bytes.NewReader(data))
678		if err := dec.Decode(&elems); err != nil {
679			return nil, fmt.Errorf("manifest is not valid JSON: %w", err)
680		}
681		var extra json.RawMessage
682		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
683			if err == nil {
684				return nil, errors.New("manifest has unexpected data after the array")
685			}
686			return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
687		}
688		if len(elems) == 0 {
689			return nil, errors.New("manifest must contain at least one record")
690		}
691	
692		inputs := make([]Input, 0, len(elems))
693		for i, raw := range elems {
694			pos := i + 1
695			in, err := parseManifestRecord(raw)
696			if err != nil {
697				return nil, &ManifestRecordError{Position: pos, Batch: in.Batch, Reason: err.Error()}
698			}
699			inputs = append(inputs, in)
700		}
701		return inputs, nil
702	}
