704	// batchRecordFields are the only members a batch record may carry, in the
705	// registry file and in an import manifest alike.
706	var batchRecordFields = map[string]struct{}{
707		"batch": {}, "product": {}, "quantity": {}, "unit": {},
708	}
709	
710	// parseManifestRecord validates one manifest element: it must be a JSON
711	// object with exactly the four required keys, text fields as non-blank,
712	// valid UTF-8 strings and quantity as a strict JSON integer. The members
713	// are scanned with parseObjectFields (strict key decoding, duplicates kept
714	// visible) rather than a lenient map unmarshal, so malformed key or value
715	// bytes cannot be silently replaced with U+FFFD. Whatever makes the record
716	// fail — an unknown, duplicated or case-mismatched field included — the
717	// returned Input carries the normalized batch id whenever exactly one
718	// "batch" member holds valid, non-blank text, so the caller can name the
719	// batch in the error; otherwise it stays empty.
720	//
721	// The structural rules are shared with parseRegistryRecord; this source's
722	// own choices are: member-name anomalies are reported in source order
723	// (unknown and duplicate carry equal weight), text is trimmed and must stay
724	// non-empty, and reasons use manifest wording (including *EncodingError for
725	// malformed text).
726	func parseManifestRecord(raw json.RawMessage) (Input, error) {
727		var in Input
728		members, err := parseObjectFields(raw)
729		if err != nil {
730			return in, errors.New("record must be a JSON object with batch, product, quantity and unit")
731		}
732		// Attach the batch id to whatever error this record raises, but only when
733		// it is unambiguous: exactly one "batch" member (compared after JSON key
734		// decoding, so an escaped respelling counts as the same field) carrying a
735		// JSON string whose decoded text is valid UTF-8 and non-blank once
736		// trimmed. A missing, duplicated, mistyped, blank or malformed "batch"
737		// member leaves the id out — never a U+FFFD substitution, and never one
738		// of two duplicate values picked arbitrarily, even when both are equal.
739		// Where the "batch" member sits relative to the offending field does not
740		// matter.
741		in.Batch = unambiguousBatchID(members, textTrimmed)
742	
743		// Manifest member-name problems are reported in source order: the first
744		// unknown name or first repeat fails the record.
745		switch fault := checkRecordMembers(members, false); fault.kind {
746		case faultUnknown:
747			return in, fmt.Errorf("record has unknown field %q; only batch, product, quantity and unit are allowed", fault.field)
748		case faultDuplicate:
749			return in, fmt.Errorf("record lists field %q more than once", fault.field)
750		}
751	
752		textField := func(name string) (string, error) {
753			rawValue, found := findField(members, name)
754			value, problem, cause := decodeRecordText(rawValue, found, textTrimmed)
755			switch problem {
756			case fieldMissing:
757				return "", fmt.Errorf("missing required field %q", name)
758			case fieldNotString:
759				return "", fmt.Errorf("field %q must be a JSON string", name)
760			case fieldEncoding:
761				return "", &EncodingError{Field: name}
762			case fieldBlank:
763				return "", fmt.Errorf("field %q must not be blank: %w", name, cause)
764			}
765			return value, nil
766		}
767	
768		in.Batch, err = textField("batch")
769		if err != nil {
770			return in, err
771		}
772		in.Product, err = textField("product")
773		if err != nil {
774			return in, err
775		}
776		in.Unit, err = textField("unit")
777		if err != nil {
778			return in, err
779		}
780		quantityRaw, ok := findField(members, "quantity")
781		if !ok {
782			return in, errors.New("missing required field \"quantity\"")
783		}
784		in.Quantity, err = manifestQuantityError(bytes.TrimSpace(quantityRaw))
785		if err != nil {
786			return in, err
787		}
788		return in, nil
789	}
790	
791	// ImportResult is one entry of an Import outcome: the normalized record in
792	// manifest order plus whether it was newly created or already present.
793	type ImportResult struct {
794		Batch   Batch
795		Created bool
796	}
797	
798	// validateManifestInput applies the same effective-value rules to one
799	// directly submitted record that Register enforces for single entries and
800	// parseManifestRecord enforces for file records: the three text fields must
801	// be valid UTF-8 and must not be empty strings, and quantity must lie in
802	// 1..MaxQuantity. Text is checked verbatim — direct submissions get no
803	// whitespace trimming or case folding (the command-line entry normalizes
804	// before constructing the Input), so whitespace-only text is accepted as
805	// ordinary non-empty text. pos is the record's 1-based position in this
806	// submission. The returned *ManifestRecordError names the offending field
807	// in its reason and cites the batch id only when that id is itself
808	// non-empty, valid UTF-8 text; it is never invented or substituted when the
809	// batch field is empty or malformed.
810	func validateManifestInput(in Input, pos int) error {
811		// batchID is "" whenever the batch field itself is empty or malformed, so
812		// it is safe to attach it to whichever error follows.
813		batchID := safeBatchIDForError(in.Batch)
814		textFields := recordTextFields(in.Batch, in.Product, in.Unit)
815		for _, tv := range textFields {
816			if !utf8.ValidString(tv.value) {
817				return &ManifestRecordError{Position: pos, Batch: batchID, Reason: (&EncodingError{Field: tv.name}).Error()}
818			}
819		}
820		for _, tv := range textFields {
821			if tv.value == "" {
822				return &ManifestRecordError{Position: pos, Batch: batchID, Reason: fmt.Sprintf("field %q must not be empty", tv.name)}
823			}
824		}
825		if in.Quantity <= 0 {
826			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: `field "quantity" must be greater than zero`}
827		}
828		if in.Quantity > MaxQuantity {
829			return &ManifestRecordError{Position: pos, Batch: batchID,
830				Reason: fmt.Sprintf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)}
831		}
832		return nil
833	}
834	
835	// Import validates every record of inputs before appending anything: the
836	// whole manifest fails if any record carries invalid UTF-8, an empty text
837	// field or a quantity outside 1..MaxQuantity — whether its batch id is new,
838	// already stored or seen earlier in this submission — or if any record
839	// conflicts with a stored record or with an earlier manifest record, and reg
840	// is left untouched on error. Directly submitted text is kept verbatim. New
841	// batch ids are appended in first-occurrence order; an id already stored or
842	// introduced earlier in the same manifest is confirmed as a duplicate only
843	// when product, quantity and unit all match. Results come back in manifest
844	// order; Created is false for duplicates.
845	func Import(reg *Registry, inputs []Input) (results []ImportResult, err error) {
846		if reg.Version != FormatVersion {
847			return nil, fmt.Errorf("unsupported registry version %d", reg.Version)
848		}
849		if len(inputs) == 0 {
850			return nil, errors.New("manifest must contain at least one record")
851		}
852		// Reject malformed text and non-effective values before touching
853		// anything; this covers records handed in directly by Go callers the
854		// same way ParseManifest covers file records, so a blank text field or a
855		// non-positive quantity can never reach the new/duplicate/conflict logic
856		// below and end up in a file the reader would refuse. Text is checked
857		// verbatim: direct submissions get no trimming or case folding (only the
858		// command-line entry normalizes, before building the Input).
859		for i, in := range inputs {
860			if err := validateManifestInput(in, i+1); err != nil {
861				return nil, err
862			}
863		}
864	
865		// Work on a copy: a rejected manifest must never partially land in reg.
866		working := append([]Batch(nil), reg.Batches...)
867		indexByID := make(map[string]int, len(working))
868		for i, b := range working {
869			indexByID[b.Batch] = i
870		}
871		firstPos := make(map[string]int, len(inputs)) // manifest 1-based position of a newly introduced id
872	
873		out := make([]ImportResult, len(inputs))
874		for i, in := range inputs {
875			pos := i + 1
876			if idx, known := indexByID[in.Batch]; known {
877				existing := working[idx]
878				diffs := diffFields(existing, in)
879				if len(diffs) > 0 {
880					if prev, inManifest := firstPos[in.Batch]; inManifest {
881						return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "manifest", PrevPos: prev}
882					}
883					return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "registry"}
884				}
885				out[i] = ImportResult{Batch: existing, Created: false}
886				continue
887			}
888			b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
889			working = append(working, b)
890			indexByID[in.Batch] = len(working) - 1
891			firstPos[in.Batch] = pos
892			out[i] = ImportResult{Batch: b, Created: true}
893		}
894	
895		reg.Batches = working
896		return out, nil
897	}
898	
899	// diffFields lists the members of product, quantity and unit in which in
900	// differs from existing, in that fixed order.
901	func diffFields(existing Batch, in Input) []string {
902		var diffs []string
903		if existing.Product != in.Product {
904			diffs = append(diffs, "product")
905		}
906		if existing.Quantity != in.Quantity {
907			diffs = append(diffs, "quantity")
908		}
909		if existing.Unit != in.Unit {
910			diffs = append(diffs, "unit")
911		}
912		return diffs
913	}
914	
915	// Register adds in to reg, or confirms the identical record already stored
916	// under the same batch id. A batch id held by a record differing in product,
917	// quantity or unit produces a *ConflictError and leaves reg untouched. The
918	// zero Outcome is returned together with the error.
919	func Register(reg *Registry, in Input) (Outcome, error) {
920		if reg.Version != FormatVersion {
921			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
922		}
923		if in.Batch == "" || in.Product == "" || in.Unit == "" {
924			return Outcome{}, errors.New("batch, product and unit must be non-empty")
925		}
926		for _, tv := range recordTextFields(in.Batch, in.Product, in.Unit) {
927			if !utf8.ValidString(tv.value) {
928				return Outcome{}, &EncodingError{Field: tv.name}
929			}
930		}
931		if !quantityInRange(in.Quantity) {
932			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
933		}
934		for _, b := range reg.Batches {
935			if b.Batch != in.Batch {
936				continue
937			}
938			if diffs := diffFields(b, in); len(diffs) > 0 {
939				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
940			}
941			return Outcome{Batch: b, Created: false}, nil
942		}
943		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
944		reg.Batches = append(reg.Batches, b)
945		return Outcome{Batch: b, Created: true}, nil
946	}
947	
948	// validateForSave checks every record of reg against the rules Load enforces,
949	// so a hand-assembled registry cannot be persisted in a shape the reader
950	// would refuse. Records are checked in order and the first violation is
951	// reported as a *FormatError naming the 1-based record position, the field
952	// and the reason; the batch id is attached only when it is itself non-empty,
953	// valid UTF-8 text — never a U+FFFD substitution for a malformed id. A batch
954	// id seen twice is reported as a *DuplicateIDError carrying both 1-based
955	// positions, even when the two records are identical: Save persists records,
956	// it never confirms duplicates or merges them. Text is checked verbatim —
957	// no trimming, no case folding — and reg is never modified.
958	func validateForSave(reg *Registry) error {
959		seen := make(map[string]int, len(reg.Batches))
960		for i, b := range reg.Batches {
961			pos := i + 1
962			batchID := safeBatchIDForError(b.Batch)
963			for _, tv := range recordTextFields(b.Batch, b.Product, b.Unit) {
964				if !utf8.ValidString(tv.value) {
965					return &FormatError{Position: pos, Batch: batchID, Field: tv.name,
966						Reason: "must be valid UTF-8 text: malformed bytes are rejected instead of being replaced with U+FFFD"}
967				}
968				if tv.value == "" {
969					return &FormatError{Position: pos, Batch: batchID, Field: tv.name, Reason: "must not be empty"}
970				}
971			}
972			if !quantityInRange(b.Quantity) {
973				return &FormatError{Position: pos, Batch: batchID, Field: "quantity",
974					Reason: fmt.Sprintf("must be between 1 and %d", MaxQuantity)}
975			}
976			if first, dup := seen[b.Batch]; dup {
977				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
978			}
979			seen[b.Batch] = pos
980		}
981		return nil
982	}
983	
984	// Save atomically writes reg to path, replacing the file only after the new
985	// content is fully on disk so an existing registry stays usable on failure.
986	// Records are serialized in their current order; the file is created with
987	// 0644 permissions or, when replacing an existing file, with its permissions.
988	//
989	// Every record must satisfy the same effective-value rules Load enforces, so
990	// a registry saved successfully always reads back: batch, product and unit
991	// must be non-empty valid UTF-8 text (kept verbatim — no trimming or case
992	// folding, so whitespace-only text is ordinary non-empty text), quantity
993	// must lie in 1..MaxQuantity, and batch ids must be unique under exact
994	// byte-for-byte comparison, two identical records included. Any violation
995	// rejects the whole save before anything is written: an existing target
996	// keeps its bytes and modification time, a missing target stays missing and
997	// no temporary file is left behind. A nil or empty Batches is a legal empty
998	// registry and is written as "batches": [] without touching reg itself.
999	func Save(path string, reg *Registry) error {
1000		if reg.Version != FormatVersion {
1001			return fmt.Errorf("cannot write registry format version %d", reg.Version)
1002		}
1003		if err := validateForSave(reg); err != nil {
1004			return fmt.Errorf("cannot save registry %q: %w", path, err)
1005		}
1006		mode := os.FileMode(0o644)
1007		if info, err := os.Stat(path); err == nil {
1008			mode = info.Mode().Perm()
1009		} else if !errors.Is(err, fs.ErrNotExist) {
1010			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
1011		}
1012	
1013		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
1014			return fmt.Errorf("cannot save registry %q: %w", path, err)
1015		}
1016	
1017		// Encode a shallow copy so a nil Batches marshals as [] (null would not
1018		// read back) without mutating the caller's registry.
1019		out := *reg
1020		if out.Batches == nil {
1021			out.Batches = []Batch{}
1022		}
1023		var buf bytes.Buffer
1024		enc := json.NewEncoder(&buf)
1025		enc.SetEscapeHTML(false)
1026		enc.SetIndent("", "  ")
1027		if err := enc.Encode(&out); err != nil {
1028			return fmt.Errorf("cannot encode registry %q: %w", path, err)
1029		}
1030	
1031		tmp, err := os.CreateTemp(filepath.Dir(path), ".govflow-registry-*.tmp")
1032		if err != nil {
1033			return fmt.Errorf("cannot save registry %q: %w", path, err)
1034		}
1035		tmpName := tmp.Name()
1036		abort := func(cause error) error {
1037			tmp.Close()
1038			os.Remove(tmpName)
1039			return fmt.Errorf("cannot save registry %q: %w", path, cause)
1040		}
1041		if _, err := tmp.Write(buf.Bytes()); err != nil {
1042			return abort(err)
1043		}
1044		if err := tmp.Chmod(mode); err != nil {
1045			return abort(err)
1046		}
1047		if err := tmp.Sync(); err != nil {
1048			return abort(err)
1049		}
1050		if err := tmp.Close(); err != nil {
1051			os.Remove(tmpName)
1052			return fmt.Errorf("cannot save registry %q: %w", path, err)
1053		}
1054		if err := os.Rename(tmpName, path); err != nil {
1055			os.Remove(tmpName)
1056			return fmt.Errorf("cannot save registry %q: %w", path, err)
1057		}
1058		return nil
1059	}
1060

