13	func TestNormalizeField(t *testing.T) {
14		cases := []struct {
15			name  string
16			in    string
17			want  string
18			valid bool
19		}{
20			{"plain", "B-001", "B-001", true},
21			{"trims ends", "\t B-001 \n", "B-001", true},
22			{"keeps interior", "B 001", "B 001", true},
23			{"keeps case", "b1", "b1", true},
24			{"empty", "", "", false},
25			{"only whitespace", " \t\n", "", false},
26		}
27		for _, tc := range cases {
28			t.Run(tc.name, func(t *testing.T) {
29				got, err := NormalizeField(tc.in)
30				if tc.valid {
31					if err != nil {
32						t.Fatalf("unexpected error: %v", err)
33					}
34					if got != tc.want {
35						t.Fatalf("got %q, want %q", got, tc.want)
36					}
37				} else if err == nil {
38					t.Fatalf("expected error for %q, got %q", tc.in, got)
39				}
40			})
41		}
42	}
