44	func TestParseQuantity(t *testing.T) {
45		const max = "9223372036854775807"
46		valid := map[string]int64{
47			"1":                   1,
48			"0007":                7,
49			"120":                 120,
50			max:                   MaxQuantity,
51			"0000000000000000001": 1,
52		}
53		for in, want := range valid {
54			got, err := ParseQuantity(in)
55			if err != nil {
56				t.Fatalf("ParseQuantity(%q) unexpected error: %v", in, err)
