59				t.Fatalf("ParseQuantity(%q) = %d, want %d", in, got, want)
60			}
61		}
62		invalid := []string{
63			"0", "0000", "-1", "+1", "1.0", "1e3", " 1", "1 ",
64			"abc", "１２", "9223372036854775808", "99999999999999999999999", "",
65		}
66		for _, in := range invalid {
67			if _, err := ParseQuantity(in); err == nil {
68				t.Fatalf("ParseQuantity(%q) expected error", in)
69			}
70		}
71	}
