73	func writeRegistry(t *testing.T, path, content string) {
74		t.Helper()
75		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
76			t.Fatal(err)
77		}
78		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
79			t.Fatal(err)
80		}
