138	func TestDuplicateDoesNotRewriteFile(t *testing.T) {
139		path := filepath.Join(t.TempDir(), "registry.json")
140		writeRegistry(t, path, `{"version":1,"batches":[{"batch":"B-1","product":"P-7","quantity":120,"unit":"kg"}]}`)
141		before, err := os.Stat(path)
142		if err != nil {
143			t.Fatal(err)
144		}
145	
146		reg, _, err := Load(path)
147		if err != nil {
148			t.Fatal(err)
149		}
150		out, err := Register(reg, Input{Batch: "B-1", Product: "P-7", Quantity: 120, Unit: "kg"})
151		if err != nil || out.Created {
152			t.Fatalf("expected duplicate, got %+v err=%v", out, err)
153		}
154		// CLI contract: a duplicate must not save. Verify in-memory state has
155		// still exactly one record.
156		if len(reg.Batches) != 1 {
157			t.Fatalf("duplicate changed in-memory registry: %+v", reg.Batches)
158		}
159		after, err := os.Stat(path)
160		if err != nil {
161			t.Fatal(err)
162		}
163		if after.ModTime() != before.ModTime() || after.Size() != before.Size() {
164			t.Fatal("duplicate registration rewrote the registry file")
165		}
166	}
