168	func TestConflictNamesFieldsAndDoesNotMutate(t *testing.T) {
169		path := filepath.Join(t.TempDir(), "registry.json")
170		writeRegistry(t, path, `{"version":1,"batches":[{"batch":"B-1","product":"P-7","quantity":120,"unit":"kg"},{"batch":"B-9","product":"P-9","quantity":3,"unit":"box"}]}`)
171	
172		cases := []struct {
173			name       string
174			in         Input
175			wantFields []string
176		}{
177			{"product", Input{Batch: "B-1", Product: "P-8", Quantity: 120, Unit: "kg"}, []string{"product"}},
178			{"quantity", Input{Batch: "B-1", Product: "P-7", Quantity: 121, Unit: "kg"}, []string{"quantity"}},
179			{"unit", Input{Batch: "B-1", Product: "P-7", Quantity: 120, Unit: "g"}, []string{"unit"}},
180			{"all", Input{Batch: "B-1", Product: "X", Quantity: 1, Unit: "Y"}, []string{"product", "quantity", "unit"}},
181		}
182		original, err := os.ReadFile(path)
183		if err != nil {
184			t.Fatal(err)
185		}
186		for _, tc := range cases {
187			t.Run(tc.name, func(t *testing.T) {
188				reg, _, err := Load(path)
189				if err != nil {
190					t.Fatal(err)
191				}
192				_, err = Register(reg, tc.in)
193				var ce *ConflictError
194				if !errors.As(err, &ce) {
195					t.Fatalf("expected ConflictError, got %v", err)
196				}
197				if ce.Batch != "B-1" {
198					t.Errorf("conflict batch = %q", ce.Batch)
199				}
200				if strings.Join(ce.Fields, ",") != strings.Join(tc.wantFields, ",") {
201					t.Errorf("fields = %v, want %v", ce.Fields, tc.wantFields)
202				}
203				if len(reg.Batches) != 2 || reg.Batches[0].Quantity != 120 || reg.Batches[0].Product != "P-7" {
204					t.Fatalf("conflict mutated in-memory records: %+v", reg.Batches)
205				}
206			})
207		}
208		after, err := os.ReadFile(path)
209		if err != nil {
210			t.Fatal(err)
211		}
212		if string(after) != string(original) {
213			t.Fatal("conflict path must not modify the file")
214		}
215	}
