349				t.Fatalf("unexpected FormatError: %+v", fe)
350			}
351		})
352	
353		// When the batch member itself is duplicated, no id is picked.
354		t.Run("ambiguous batch id", func(t *testing.T) {
355			path := filepath.Join(dir, "amb.json")
