59	// A registry with no batches at all is legal: whether the caller never
60	// initialized the slice or emptied it, the file must hold an empty JSON
61	// array — never null — and read back as an empty registry. Save must not
62	// patch the caller's slice to get there.
63	func TestSaveEmptyRegistryWritesEmptyArray(t *testing.T) {
64		cases := []struct {
65			name    string
66			batches []Batch
67			wantNil bool
68		}{
69			{"uninitialized batches", nil, true},
70			{"already empty batches", []Batch{}, false},
