112	// A successful save persists records exactly as the caller supplied them:
113	// order and all four fields survive the round trip through Load, including
114	// quantity bounds, non-ASCII text, a genuine U+FFFD the user really typed,
115	// and every kind of whitespace — Save never trims or folds text.
116	func TestSaveRoundTripsRecordsVerbatim(t *testing.T) {
117		fffd := string(rune(0xfffd))
118		records := []Batch{
119			{Batch: "B-001", Product: "P-7", Quantity: 1, Unit: "kg"},
120			{Batch: "B-002", Product: "P-8", Quantity: MaxQuantity, Unit: "box"},
